D.CICLO={
 estados:{
  magma:{nome:'Magma',cor:'#ff7a20',text:'Rocha derretida, a mais de 700 graus, dentro da Terra. Daqui tudo começa.',audio:'roc-ciclo-magma'},
  ignea:{nome:'Rocha ígnea',cor:'#9a8c80',text:'O magma esfriou e endureceu. Devagar, lá embaixo, dá granito, de grãos grandes; rápido, na superfície, dá basalto, de grãos miúdos.',audio:'roc-ciclo-ignea'},
  sedimento:{nome:'Sedimento',cor:'#d8b878',text:'Chuva, vento, gelo e rios quebraram a rocha em pedaços: cascalho, areia, lama. A água carrega tudo para baixo, até o fundo de um lago ou do mar.',audio:'roc-ciclo-sedimento'},
  sedimentar:{nome:'Rocha sedimentar',cor:'#e0c08a',text:'Camada sobre camada, o peso apertou os grãos e a água cimentou: o sedimento virou rocha, como o arenito e o calcário. É aqui que os fósseis ficam guardados.',audio:'roc-ciclo-sedimentar'},
  metamorfica:{nome:'Rocha metamórfica',cor:'#c8c0d8',text:'Enterrada fundo, cozida e apertada, a rocha mudou sem derreter: os minerais se reorganizaram. O calcário virou mármore; a argila virou ardósia.',audio:'roc-ciclo-metamorfica'}
 },
 ordem:['magma','ignea','sedimento','sedimentar','metamorfica'],
 processos:[
  {id:'esfriar',nome:'Esfriar e endurecer',de:['magma'],para:'ignea',text:'O magma esfriou e cristalizou: nasceu uma rocha ígnea.'},
  {id:'erodir',nome:'Intemperismo e erosão',de:['ignea','sedimentar','metamorfica'],para:'sedimento',text:'Chuva, vento e gelo quebraram a rocha; os rios levaram os grãos embora.'},
  {id:'compactar',nome:'Compactar e cimentar',de:['sedimento'],para:'sedimentar',text:'Camadas de sedimento, apertadas e coladas: virou rocha sedimentar.'},
  {id:'metamorfizar',nome:'Calor e pressão',de:['ignea','sedimentar'],para:'metamorfica',text:'Enterrada fundo, cozida e espremida: a rocha mudou sem derreter.'},
  {id:'derreter',nome:'Derreter',de:['ignea','sedimentar','metamorfica'],para:'magma',text:'Fundo demais, quente demais: a rocha virou magma de novo. O ciclo recomeça.'}
 ]
};
D.CICLO_FIM={text:'Você passou pelos cinco estados: magma, ígnea, sedimento, sedimentar e metamórfica. Qualquer rocha pode virar qualquer outra; só depende do caminho e de muito tempo.',audio:'roc-ciclo-concluido'};
/* que rocha é essa? cinco rodadas com pistas */
D.IDENTIFICAR=[
 {amostra:'basalto',pistas:['Escura, quase preta','Grãos tão finos que não dá para ver','Algumas bolhinhas de gás'],opcoes:['basalto','granito','ardosia'],why:'Escura e de grãos finos: é o basalto, lava que esfriou rápido na superfície. O granito teria grãos grandes e claros; a ardósia se partiria em placas.'},
 {amostra:'arenito',pistas:['Cor de areia','Dá para ver os grãos, parecem colados','Tem camadas horizontais'],opcoes:['marmore','arenito','obsidiana'],why:'Grãos de areia colados em camadas: é o arenito, rocha sedimentar. O mármore é liso e com veios; a obsidiana é um vidro preto.'},
 {amostra:'marmore',pistas:['Clara, branca ou creme','Lisa, com veios cinza','Brilha quando polida'],opcoes:['calcario','arenito','marmore'],why:'Branco com veios e brilho: é o mármore, calcário que foi cozido e apertado. O calcário é mais fosco e pode ter fósseis.'},
 {amostra:'obsidiana',pistas:['Preta e brilhante como vidro','Sem grãos nenhum','Quebra em lascas afiadas'],opcoes:['carvao','obsidiana','basalto'],why:'Vidro vulcânico: a lava esfriou tão rápido que nem formou cristais. O carvão é preto, mas fosco e leve; o basalto tem grãos.'},
 {amostra:'granito',pistas:['Clara, com pintas rosa, branco e preto','Grãos grandes, dá para ver cada um','Dura e pesada'],opcoes:['granito','pomes','arenito'],why:'Pintas de quartzo, feldspato e mica, grãos grandes: granito, magma que esfriou devagar no fundo. A pedra-pomes é leve e cheia de furos.'}
];
D.IDENTIFICAR_FIM={text:'Cinco amostras identificadas. Cor, tamanho dos grãos, camadas, brilho e bolhas: com essas pistas dá para ler a história de quase qualquer pedra.',audio:'roc-identificar-concluido'};
/* contexto em três etapas (cena muda a cada etapa) */
D.context=[
 {name:'Planeta Terra',target:'aberta',text:'Esta é a Terra vista do espaço: uma bola de rocha e metal com 12.742 quilômetros de diâmetro. A gente vive na superfície e quase nunca pensa no que tem lá embaixo. Vamos abrir o planeta ao meio.'},
 {name:'A Terra por dentro',target:'crosta',text:'Aberta ao meio, a Terra mostra as suas camadas: a crosta fininha por fora, o manto enorme no meio, e no centro o núcleo, de ferro e níquel, com a parte de fora líquida e a de dentro sólida. Olhe agora bem de perto a camada onde a gente vive.'},
 {name:'A casca fina',text:'A crosta é a casca da Terra. Comparando com uma maçã, ela é mais fina que a casca da fruta: no oceano tem uns 7 quilômetros, nos continentes de 30 a 70. Tudo o que o ser humano já perfurou, cerca de 12 quilômetros, não chegou nem a atravessá-la.'}
];
/* fichas (chaves = nomes dos áudios) */
D.info={
 terra:{name:'Terra',kind:'Planeta',color:'#6fb7e0',text:'A Terra tem 6.371 quilômetros de raio e é feita de camadas, como uma cebola: crosta, manto e núcleo. Quanto mais fundo, mais quente e mais apertado.',detail:'Diâmetro: 12.742 km. Idade: cerca de 4,5 bilhões de anos. É o planeta rochoso mais denso do Sistema Solar, por causa do núcleo metálico.',medio:'A diferenciação em camadas aconteceu no início da formação do planeta: os materiais mais densos (ferro e níquel) afundaram para o centro, e os silicatos, mais leves, ficaram por fora.'},
 crosta:{name:'Crosta',kind:'Camada externa · sólida',color:'#8fd0a0',text:'A crosta é a camada de fora, onde a gente vive. É de rocha sólida e fininha: de 5 a 70 quilômetros. Debaixo dos oceanos é mais fina e mais pesada; nos continentes é mais grossa e mais leve.',detail:'Duas crostas diferentes: a continental (granito, 30 a 70 km, mais antiga) e a oceânica (basalto, 5 a 10 km, mais densa). A fronteira com o manto chama-se descontinuidade de Mohorovičić, a "Moho".',medio:'A crosta corresponde a menos de 1% da massa da Terra. A oceânica é renovada nas dorsais e destruída nas zonas de subducção; por isso nenhuma rocha do fundo do mar tem mais de 200 milhões de anos.'},
 crosta_continental:{name:'Crosta continental',kind:'Crosta · 30 a 70 km',color:'#a8d8a0',text:'Esta é a crosta continental: a parte grossa, de granito, que forma os continentes. Chega a 70 quilômetros debaixo das grandes montanhas. É a rocha mais antiga do planeta: algumas têm 4 bilhões de anos.',detail:'Menos densa que a oceânica, ela "boia" sobre o manto. Por isso os continentes ficam acima do nível do mar.',medio:'Densidade média de 2,7 g/cm³, rica em sílica e alumínio. Em colisões de placas ela dobra e se espessa, formando cadeias como os Andes e o Himalaia.'},
 crosta_oceanica:{name:'Crosta oceânica',kind:'Crosta · 5 a 10 km',color:'#5fa8c8',text:'Esta é a crosta oceânica: fina, escura, de basalto. Fica no fundo dos mares. Ela nasce nas dorsais, onde a lava sobe, e é jovem: nenhuma parte tem mais de 200 milhões de anos.',detail:'Mais densa que a continental (3,0 g/cm³). Quando encontra um continente, mergulha por baixo dele: é a subducção.',medio:'Formada pelo resfriamento do basalto nas dorsais meso-oceânicas, registra as inversões do campo magnético em faixas simétricas, uma das provas da tectônica de placas.'},
 litosfera:{name:'Litosfera',kind:'Crosta + topo do manto · rígida',color:'#c9c2a0',text:'A litosfera é a crosta mais o pedacinho de cima do manto, tudo rígido, com uns 100 quilômetros. É ela que está quebrada em placas, as placas tectônicas, que se movem devagar sobre a camada mole de baixo.',detail:'As placas se movem de 2 a 10 cm por ano, mais ou menos a velocidade com que a sua unha cresce.',medio:'O limite inferior da litosfera é térmico (isoterma de cerca de 1.300 °C), não de composição: abaixo dela a mesma rocha passa a se comportar de modo dúctil.'},
 astenosfera:{name:'Astenosfera',kind:'Manto superior · plástica',color:'#e0a060',text:'Logo abaixo da litosfera vem a astenosfera. A rocha aqui é tão quente que fica mole, como uma massa de modelar. É sobre ela que as placas deslizam.',detail:'Vai de cerca de 100 a 350 km de profundidade. Não é líquida: é sólida, mas se deforma devagar.',medio:'Uma pequena fração de rocha parcialmente fundida reduz a rigidez e a velocidade das ondas sísmicas (zona de baixa velocidade), o que permitiu identificá-la.'},
 manto_superior:{name:'Manto superior',kind:'Manto · até 660 km',color:'#e07a3c',text:'O manto superior vai até 660 quilômetros de profundidade. É rocha quente, de 1.000 a 1.600 graus, que se mexe muito devagar, como caramelo. Esse movimento empurra as placas lá em cima.',detail:'Feito principalmente de peridotito, uma rocha rica em olivina, um mineral verde. Inclui a astenosfera.',medio:'A 410 km e a 660 km a olivina muda de estrutura cristalina com a pressão (transições de fase), o que separa o manto superior do inferior e aparece nas ondas sísmicas.'},
 manto_inferior:{name:'Manto inferior',kind:'Manto · 660 a 2.900 km',color:'#c84a28',text:'O manto inferior é a maior camada da Terra: vai de 660 até 2.900 quilômetros. Sozinho, o manto todo tem 84 por cento do volume do planeta. Aqui a temperatura chega a 3.700 graus, mas a pressão é tão grande que a rocha continua sólida.',detail:'A rocha se move por convecção: a quente sobe, a fria desce, em correntes que levam milhões de anos para dar uma volta.',medio:'Composto por bridgmanita e ferropericlase, estáveis sob alta pressão. Na base, a camada D″ interage com o núcleo e pode originar as plumas mantélicas (como a do Havaí).'},
 nucleo_externo:{name:'Núcleo externo',kind:'Núcleo · líquido · 2.900 a 5.150 km',color:'#f0a030',text:'O núcleo externo é um oceano de metal derretido: ferro e níquel líquidos a mais de 4.000 graus. Ele gira e se mexe, e é esse movimento que cria o campo magnético da Terra, o escudo que protege a gente do vento solar.',detail:'Sabemos que é líquido porque as ondas sísmicas do tipo S, que não atravessam líquidos, somem quando chegam nele.',medio:'O geodínamo: a convecção de metal condutor, combinada com a rotação da Terra, gera correntes elétricas que sustentam o campo magnético. O campo inverte de polaridade em intervalos irregulares.'},
 nucleo_interno:{name:'Núcleo interno',kind:'Núcleo · sólido · 5.150 a 6.371 km',color:'#fff0a0',text:'No centro de tudo, o núcleo interno: uma bola de ferro sólido com 1.220 quilômetros de raio, quase do tamanho da Lua. É o lugar mais quente da Terra, uns 5.400 graus, tão quente quanto a superfície do Sol. Mas é sólido, porque a pressão é gigantesca.',detail:'A pressão no centro é de cerca de 3,6 milhões de vezes a pressão do ar na superfície.',medio:'Descoberto em 1936 pela sismóloga Inge Lehmann. Cresce lentamente conforme o núcleo externo se solidifica, liberando calor que ajuda a mover o geodínamo.'},
 moho:{name:'Descontinuidade de Moho',kind:'Fronteira crosta · manto',color:'#d8e8c0',text:'A Moho é a linha que separa a crosta do manto. Ela foi descoberta em 1909 por Andrija Mohorovičić, que percebeu que as ondas dos terremotos aceleravam de repente ao cruzar essa profundidade.',detail:'Fica a 5 a 10 km sob os oceanos e a 30 a 70 km sob os continentes.',medio:'Marca a mudança de rochas da crosta (granito, basalto) para o peridotito do manto, mais denso, o que aumenta a velocidade das ondas P de ~7 para ~8 km/s.'},
 ondas_sismicas:{name:'Ondas sísmicas',kind:'Como conhecemos o interior',color:'#9fd0ff',text:'Ninguém nunca viu o interior da Terra. Tudo o que sabemos veio dos terremotos: as ondas que eles produzem atravessam o planeta e mudam de velocidade e de direção em cada camada. Os sismógrafos do mundo inteiro registram isso, e os cientistas montam a imagem de dentro.',detail:'Ondas P atravessam sólidos e líquidos; ondas S só atravessam sólidos. Como as S desaparecem no núcleo externo, descobrimos que ele é líquido.',medio:'A "zona de sombra" das ondas S (entre 104° e 180° do epicentro) e a refração das ondas P no núcleo permitiram a Gutenberg (1914) medir o raio do núcleo.'},
 campo_magnetico:{name:'Campo magnético',kind:'Escudo da Terra',color:'#b0a0ff',text:'A Terra é um ímã gigante por causa do núcleo externo: o ferro líquido em movimento gera o campo magnético. É ele que faz a bússola apontar para o norte e que desvia as partículas do Sol, formando as auroras nos polos.',detail:'Sem o campo magnético, o vento solar arrancaria a atmosfera aos poucos, como aconteceu em Marte.',medio:'O campo é aproximadamente dipolar, com intensidade de 25 a 65 microteslas na superfície. Os polos magnéticos migram e o campo já inverteu centenas de vezes.'},
 pacifica:{name:'Placa do Pacífico',kind:'Placa oceânica · a maior',color:'#7fc8ff',text:'A placa do Pacífico é a maior de todas, e é quase toda oceânica: debaixo dela só tem fundo de mar. Ela está rodeada pelo Anel de Fogo, a faixa de vulcões e terremotos que vai do Chile ao Japão.',detail:'Move-se para noroeste cerca de 7 a 10 cm por ano. O Havaí nasceu de um ponto quente no meio dela.',medio:'Como é oceânica e densa, mergulha sob as placas vizinhas em quase toda a sua borda: por isso o Anel de Fogo concentra 75% dos vulcões ativos do mundo.'},
 norteamericana:{name:'Placa Norte-Americana',kind:'Placa continental',color:'#ffb27a',text:'A placa Norte-Americana carrega os Estados Unidos, o Canadá, a Groenlândia e metade do oceano Atlântico. Ela se afasta da Europa pela dorsal e esfrega na placa do Pacífico na falha de San Andreas.',detail:'Afasta-se da placa Euroasiática a cerca de 2,5 cm por ano.',medio:'Inclui também o nordeste da Sibéria e o Japão setentrional: o limite com a Euroasiática não coincide com a divisão dos continentes.'},
 sulamericana:{name:'Placa Sul-Americana',kind:'Placa continental',color:'#9ee09e',text:'A nossa placa. Ela carrega a América do Sul inteira e metade do Atlântico Sul. Do lado do Pacífico, a placa de Nazca mergulha debaixo dela e levanta os Andes. O Brasil fica bem no meio, longe de tudo isso.',detail:'Move-se para oeste, cerca de 2 a 3 cm por ano, afastando-se da África.',medio:'A borda oeste é um limite convergente (subducção de Nazca); a leste, a dorsal Meso-Atlântica é divergente. No interior estável, o cráton brasileiro tem rochas de mais de 2 bilhões de anos.'},
 africana:{name:'Placa Africana',kind:'Placa continental',color:'#ffd27f',text:'A placa Africana carrega o continente africano e está se rasgando ao meio: o Vale do Rift, no leste da África, é uma fenda que um dia vai virar um oceano. Os grandes lagos africanos ficam dentro dela.',detail:'Afasta-se da América do Sul pela dorsal Meso-Atlântica.',medio:'O rifte leste-africano separa a subplaca Somali da Núbia; é um exemplo atual de limite divergente em continente, estágio inicial da abertura de um oceano.'},
 euroasiatica:{name:'Placa Euroasiática',kind:'Placa continental',color:'#d0a6ff',text:'A placa Euroasiática vai de Portugal até o Japão: Europa e a maior parte da Ásia. No sul, ela recebe o empurrão da Índia, que levantou o Himalaia, e da África, que levanta os Alpes.',detail:'É das placas mais lentas: 1 a 2 cm por ano.',medio:'Colisões continentais no seu limite sul (Alpes, Cáucaso, Himalaia) produzem as maiores montanhas do planeta, sem subducção de crosta oceânica.'},
 indoaustraliana:{name:'Placa Indo-Australiana',kind:'Placa mista',color:'#ff9aa8',text:'A placa Indo-Australiana carrega a Índia e a Austrália. Ela é a viajante: a Índia saiu de perto da Antártida, cruzou o oceano a 15 centímetros por ano e bateu na Ásia. Esse choque fez o Himalaia.',detail:'Hoje avança para o norte a cerca de 6 cm por ano.',medio:'Alguns modelos a dividem em placa Indiana e placa Australiana, separadas por uma zona difusa de deformação no oceano Índico.'},
 antartica:{name:'Placa Antártica',kind:'Placa continental e oceânica',color:'#d8ecff',text:'A placa Antártica fica no fundo do mundo: o continente gelado e o oceano em volta. Quase toda a sua borda é divergente, então ela é cercada de dorsais e tem poucos terremotos.',detail:'É quase estacionária: as outras placas se afastam dela.',medio:'Como as bordas são quase todas divergentes, a placa cresce de todos os lados; isso a torna uma referência útil para medir o movimento das demais.'},
 nazca:{name:'Placa de Nazca',kind:'Placa oceânica',color:'#9ff3ff',text:'A placa de Nazca é um pedaço de fundo de mar na frente do Chile e do Peru. Ela mergulha debaixo da América do Sul, e é esse mergulho que faz os vulcões dos Andes e os maiores terremotos já medidos, como o do Chile em 1960.',detail:'Nasce na dorsal do Pacífico Leste e some na fossa Peru-Chile.',medio:'O terremoto de Valdívia (1960, magnitude 9,5) ocorreu nessa zona de subducção; a fossa Peru-Chile chega a 8 km de profundidade.'},
 divergente:{name:'Limite divergente',kind:'As placas se afastam',color:'#ffb27a',text:'No limite divergente, duas placas se afastam. O magma sobe pela fenda, esfria e vira rocha nova: é assim que nasce fundo de oceano. As dorsais no meio dos oceanos são isso: cordilheiras submarinas de lava.',detail:'Exemplo: a dorsal Meso-Atlântica, que passa pela Islândia.',medio:'A crosta oceânica nova registra o campo magnético da época em faixas simétricas, evidência decisiva da expansão do assoalho oceânico.'},
 convergente:{name:'Limite convergente',kind:'As placas se chocam',color:'#ff7a5a',text:'No limite convergente, duas placas se chocam. Se uma é oceânica, ela mergulha por baixo da outra, derrete e vira vulcão: a subducção. Se as duas são continentais, nenhuma afunda e a crosta dobra para cima: nascem montanhas.',detail:'Exemplos: os Andes (subducção) e o Himalaia (colisão continental).',medio:'A placa que mergulha arrasta água para o manto, baixando o ponto de fusão da rocha: por isso os vulcões ficam em arco, a cerca de 100 km da fossa.'},
 transformante:{name:'Limite transformante',kind:'As placas deslizam',color:'#ffe08a',text:'No limite transformante, as placas não se chocam nem se afastam: deslizam uma ao lado da outra. A rocha trava, acumula força por décadas e solta de uma vez. Esse estalo é o terremoto.',detail:'Exemplo: a falha de San Andreas, na Califórnia.',medio:'Não cria nem destrói crosta. Os sismos são rasos (até 20 km), o que os torna muito destrutivos nas cidades próximas.'},
 terremoto:{name:'Terremoto',kind:'Fenômeno',color:'#ff6b6b',text:'Terremoto é a rocha estalando. Quando duas placas travam e a força acumulada vence, a rocha se parte e libera energia em ondas que sacodem o chão. A escala de magnitude mede essa energia: cada ponto a mais é 32 vezes mais energia.',detail:'O ponto de origem, em profundidade, é o hipocentro; na superfície, acima dele, o epicentro.',medio:'As ondas P chegam primeiro e as S depois; a diferença de tempo entre elas permite calcular a distância do epicentro em cada sismógrafo.'},
 tsunami:{name:'Tsunami',kind:'Fenômeno',color:'#5fa8c8',text:'Tsunami é a onda gigante que nasce quando um terremoto levanta o fundo do mar de repente. No oceano aberto ela passa quase sem ser notada, mas perto da costa cresce e invade a terra. Foi o que aconteceu no Japão em 2011.',detail:'Viaja a até 800 km por hora, a velocidade de um avião.',medio:'A altura cresce ao se aproximar da costa porque a velocidade cai com a profundidade e a energia se concentra: a onda "freia" e empilha.'},
 pangeia:{name:'Pangeia e a deriva',kind:'História da Terra',color:'#c9a070',text:'Há 250 milhões de anos todos os continentes estavam juntos num só, a Pangeia. Alfred Wegener percebeu isso em 1912 olhando o encaixe da costa do Brasil com a da África, e fósseis iguais nos dois lados. Os continentes se separaram devagar, carregados pelas placas.',detail:'Wegener não sabia o que movia os continentes; a resposta, o manto em convecção, só veio nos anos 1960.',medio:'Evidências: encaixe das costas, continuidade de cadeias de montanhas e rochas, fósseis de Mesosaurus na América do Sul e na África, e marcas glaciais em continentes hoje tropicais.'},
 anel_fogo:{name:'Anel de Fogo',kind:'Região',color:'#ffa040',text:'O Anel de Fogo é a faixa em volta do oceano Pacífico onde ficam três de cada quatro vulcões ativos do mundo e a maior parte dos terremotos fortes. Vai do Chile até o Alasca, desce pelo Japão e chega à Nova Zelândia.',detail:'Cerca de 40 mil km de comprimento e 450 vulcões.',medio:'É o conjunto das zonas de subducção que cercam a placa do Pacífico e as placas oceânicas menores (Nazca, Cocos, Filipina).'},
 camara_magmatica:{name:'Câmara de magma',kind:'Parte do vulcão · 2 a 10 km de profundidade',color:'#ff7a20',text:'A câmara de magma é a bolsa de rocha derretida embaixo do vulcão, a uns poucos quilômetros de profundidade. Ali o magma fica guardado, quente e cheio de gás, até a pressão ser grande demais. Quando a câmara se esvazia depois de uma erupção enorme, o teto pode desabar e virar uma caldeira.',detail:'Temperatura do magma: 700 a 1.300 °C. As câmaras não são cavernas cheias de líquido: são regiões de rocha parcialmente derretida, como uma esponja encharcada.',medio:'A câmara é alimentada por magma que sobe do manto por diferença de densidade. A cristalização dentro dela muda a composição do magma restante (diferenciação magmática), tornando-o mais rico em sílica e mais viscoso.'},
 conduto:{name:'Conduto',kind:'Parte do vulcão · o caminho do magma',color:'#ff5a10',text:'O conduto é o tubo que liga a câmara de magma à cratera. Por ele o magma sobe quando a pressão aperta. Em vulcões antigos, o magma que endureceu dentro do conduto forma uma coluna de rocha dura, o neck, que aparece quando o resto do cone é levado pela erosão.',detail:'Pode ter alguns metros ou dezenas de metros de largura. Vulcões grandes têm vários condutos e fissuras laterais.',medio:'Conforme o magma sobe pelo conduto, a pressão diminui e os gases dissolvidos formam bolhas (vesiculação), o que acelera a subida e pode fragmentar o magma em piroclastos.'},
 cratera:{name:'Cratera',kind:'Parte do vulcão · a boca',color:'#ffb27a',text:'A cratera é a boca do vulcão, a depressão em forma de funil no topo do cone por onde a erupção sai. Em alguns vulcões ela guarda um lago de lava; em outros, depois de muito tempo parado, enche de água da chuva e vira um lago comum.',detail:'Costuma ter de dezenas de metros a 1 km de largura. Não confundir com caldeira, que é muito maior e nasce de um desabamento.',medio:'Crateras são construídas pela acumulação de material ao redor do conduto e podem ser alargadas por explosões que arrancam parte do topo do edifício vulcânico.'},
 cone:{name:'Cone vulcânico',kind:'Parte do vulcão · o edifício',color:'#8a7a6a',text:'O cone é a montanha do vulcão, e ele é feito das próprias erupções: cada camada é uma erupção antiga, lava endurecida ou cinzas, uma em cima da outra. Por isso os vulcões crescem ao longo de milhares de anos. Olhando o corte, dá para contar as erupções como anéis de uma árvore.',detail:'O Fuji tem 3.776 m; o Mauna Kea, no Havaí, medido desde o fundo do mar, passa de 10 km: é a maior montanha da Terra.',medio:'Estratovulcões alternam camadas de lava e de piroclastos (estratos), daí o nome. Vulcões em escudo são feitos quase só de lavas fluidas sobrepostas.'},
 magma:{name:'Magma',kind:'Material · rocha derretida dentro da Terra',color:'#ff6a30',text:'Magma é rocha derretida enquanto ainda está dentro da Terra, misturada com gases e cristais. Ele nasce no manto ou na base da crosta e sobe porque é mais leve que a rocha em volta. O magma tem nome e comportamento diferentes conforme a quantidade de sílica: pouca sílica, fluido; muita sílica, viscoso.',detail:'Temperatura: 700 a 1.300 °C. O magma basáltico (pouca sílica) é o mais fluido; o riolítico (muita sílica) é o mais viscoso.',medio:'A viscosidade cresce com o teor de SiO₂ porque os tetraedros de sílica se ligam em cadeias. Magmas basálticos têm ~50% de SiO₂; riolíticos, ~70%.'},
 lava:{name:'Lava',kind:'Material · o magma do lado de fora',color:'#ff8a3c',text:'Lava é o mesmo magma, só que já fora da Terra. Quando sai pela cratera ou por uma fissura, perde os gases e começa a esfriar. A lava fluida corre como um rio e forma mantos lisos; a viscosa anda devagar e se empilha. Ao endurecer, vira rocha vulcânica, como o basalto.',detail:'A lava fluida pode correr a 30 km/h em encostas íngremes. No Havaí, os rios de lava chegam ao mar e criam terra nova.',medio:'Tipos de superfície da lava basáltica: pahoehoe (lisa, em cordas) e aa (áspera, em blocos). A lava almofadada (pillow) forma-se debaixo d’água, nas dorsais.'},
 nuvem_cinzas:{name:'Nuvem de cinzas',kind:'Material · rocha pulverizada',color:'#b9b2a8',text:'A nuvem cinza que sobe do vulcão não é fumaça: são cinzas, pedacinhos de rocha e vidro vulcânico menores que um grão de areia, lançados pela explosão. A coluna pode subir dezenas de quilômetros e o vento espalha as cinzas por países inteiros, fechando aeroportos e cobrindo cidades.',detail:'Em 2010, as cinzas do Eyjafjallajökull, na Islândia, pararam os aviões da Europa por uma semana.',medio:'Cinzas finas na estratosfera refletem luz solar e podem resfriar o clima global por um ou dois anos, como após o Pinatubo (1991) e o Tambora (1815, o “ano sem verão”).'},
 piroclastos:{name:'Piroclastos',kind:'Material · fragmentos lançados',color:'#5a4a40',text:'Piroclasto quer dizer “pedaço de fogo”: é tudo o que o vulcão lança quebrado. Vai das cinzas finas até as bombas vulcânicas, blocos de lava do tamanho de um carro que voam pelo ar. O mais perigoso é o fluxo piroclástico: uma avalanche de gás e cinza a 600 graus, que desce o vulcão a mais de 100 quilômetros por hora.',detail:'Pompeia foi soterrada por cinzas e fluxos piroclásticos, não por lava.',medio:'Classificação por tamanho: cinza (< 2 mm), lapíli (2 a 64 mm) e blocos ou bombas (> 64 mm). As bombas saem ainda moles e ganham forma aerodinâmica no ar.'},
 gases_vulcanicos:{name:'Gases vulcânicos',kind:'Material · o motor da erupção',color:'#cfe0f0',text:'O magma é cheio de gás dissolvido, principalmente vapor de água e gás carbônico, como um refrigerante fechado. Quando o magma sobe e a pressão cai, o gás vira bolhas e empurra tudo para fora: é o gás que faz a erupção. As fumarolas, buracos que soltam vapor e enxofre, mostram que o vulcão está vivo lá embaixo.',detail:'Medir os gases é um dos jeitos de prever erupções: quando o dióxido de enxofre aumenta, o magma está subindo.',medio:'Composição típica: H₂O (60 a 90%), CO₂, SO₂, H₂S, HCl. O CO₂ pode se acumular em lagos vulcânicos e escapar de repente, como em Nyos (1986).'},
 estratovulcao:{name:'Estratovulcão',kind:'Tipo de vulcão · cone alto e explosivo',color:'#8a6a5a',text:'O estratovulcão é o vulcão de desenho: cone alto, pontudo, com encostas íngremes. É feito de camadas alternadas de lava e cinzas. O magma viscoso e cheio de gás faz dele o tipo mais explosivo. Fuji, Vesúvio, Etna e os vulcões dos Andes são estratovulcões.',detail:'A maioria fica nas zonas de subducção, no Anel de Fogo.',medio:'Também chamado de vulcão composto. A alternância de estratos de lava (que dão resistência) e de piroclastos (que dão volume) permite que cresçam até vários quilômetros.'},
 escudo:{name:'Vulcão em escudo',kind:'Tipo de vulcão · baixo, largo e manso',color:'#9a8a6a',text:'O vulcão em escudo é baixo e muito largo, como um escudo deitado no chão. Ele é feito de lava fluida que escorre para longe antes de endurecer, camada sobre camada. As erupções são mansas, de rios de lava. Os vulcões do Havaí são os maiores exemplos: o Mauna Loa tem 120 quilômetros de largura.',detail:'O maior vulcão do Sistema Solar, o Monte Olimpo, em Marte, é um vulcão em escudo com 600 km de largura.',medio:'Formados por lavas basálticas de baixa viscosidade, em geral sobre pontos quentes ou em zonas de rifte. Encostas de apenas 5 a 10 graus.'},
 caldeira:{name:'Caldeira',kind:'Tipo de vulcão · o teto que desabou',color:'#c9a070',text:'Caldeira é o que sobra quando uma erupção gigante esvazia a câmara de magma e o vulcão inteiro desaba para dentro do buraco. Fica uma panela enorme, de quilômetros de largura, que às vezes vira um lago. Yellowstone, nos Estados Unidos, é uma caldeira de 70 quilômetros; Poços de Caldas, no Brasil, tem 30.',detail:'As maiores erupções da história da Terra formaram caldeiras: Toba (74 mil anos atrás) lançou 2.800 km³ de material.',medio:'Supervulcões são sistemas de caldeira capazes de erupções de índice VEI 8. O ressurgimento (soerguimento do piso da caldeira) indica recarga da câmara.'},
 ponto_quente:{name:'Ponto quente',kind:'Origem do magma · vulcão no meio da placa',color:'#ffa040',text:'A maioria dos vulcões fica nas fronteiras das placas, mas o Havaí está bem no meio da placa do Pacífico. É um ponto quente: uma pluma de manto quente sobe de muito fundo e fura a placa. Como a placa se move e a pluma fica parada, nasce uma fila de ilhas: as mais velhas vão se afastando e apagando.',detail:'A cadeia havaiana tem mais de 80 vulcões ao longo de 6 mil km; só os da ponta, como o Kilauea, estão ativos.',medio:'Plumas mantélicas podem ter origem no limite manto-núcleo. Outros exemplos: Islândia (ponto quente sobre uma dorsal), Galápagos, Reunião, Yellowstone.'},
 vulcao_ativo:{name:'Ativo, dormente ou extinto',kind:'Estado do vulcão',color:'#ffe08a',text:'Um vulcão ativo entrou em erupção nos últimos 10 mil anos e pode voltar a qualquer momento, como o Etna. Dormente é o que está quieto há séculos, mas ainda tem magma embaixo, como o Fuji. Extinto é o que não tem mais como entrar em erupção, porque a fonte de magma acabou, como os antigos vulcões do Brasil.',detail:'Existem cerca de 1.500 vulcões ativos no mundo, e uns 50 entram em erupção por ano.',medio:'A classificação é imprecisa: o Vesúvio e o Pinatubo eram considerados dormentes antes de erupções grandes. O monitoramento usa sismos, deformação do solo e gases.'},
 granito:{name:'Granito',kind:'Rocha ígnea · esfriou devagar',color:'#d8b8a8',text:'O granito é a rocha das montanhas e das pedras de pia. Nasceu de magma que esfriou bem devagar, lá no fundo, e por isso os grãos cresceram grandes: dá para ver o quartzo branco, o feldspato rosado e a mica brilhante a olho nu. É duro e resiste por milhões de anos.',detail:'Pão de Açúcar e Corcovado, no Rio, são granito e gnaisse. O granito é a rocha mais comum da crosta continental.',medio:'Rocha plutônica (intrusiva), felsica: quartzo, feldspatos (ortoclásio e plagioclásio) e micas. Textura fanerítica indica resfriamento lento.'},
 basalto:{name:'Basalto',kind:'Rocha ígnea · esfriou rápido',color:'#4a4440',text:'O basalto é lava que esfriou rápido na superfície. Por isso é escuro e de grãos miúdos, que não dá para ver. Às vezes tem bolhinhas, que eram gás preso na lava. O fundo de todos os oceanos é feito de basalto, e no Brasil ele cobre o sul inteiro, formando a terra roxa.',detail:'Os paredões do Parque de Vila Velha e os derrames da bacia do Paraná (um dos maiores do mundo) são basalto.',medio:'Rocha vulcânica (extrusiva), máfica: plagioclásio e piroxênio, pobre em sílica. Textura afanítica; vesículas quando o gás escapa.'},
 obsidiana:{name:'Obsidiana',kind:'Rocha ígnea · vidro vulcânico',color:'#1a1a22',text:'A obsidiana é um vidro de verdade, feito pela natureza: lava que esfriou tão depressa que não deu tempo de formar cristais. É preta, brilhante e quebra em lascas afiadas como navalha. Povos antigos faziam facas e pontas de flecha com ela.',detail:'Lâminas de obsidiana ainda são usadas em bisturis experimentais, por serem mais finas que o aço.',medio:'Vidro vulcânico riolítico, rico em sílica, com fratura conchoidal. A ausência de estrutura cristalina a classifica como mineraloide.'},
 pomes:{name:'Pedra-pomes',kind:'Rocha ígnea · cheia de furos',color:'#d8d4cc',text:'A pedra-pomes é a espuma da lava: sai do vulcão cheia de gás, esfria rápido e fica crivada de furinhos. É tão leve que boia na água. Depois de erupções grandes, jangadas de pomes atravessam o oceano.',detail:'Usada para lixar pés e para fazer concreto leve.',medio:'Piroclasto vesicular de composição félsica, formado em erupções explosivas; densidade inferior a 1 g/cm³ por causa das vesículas.'},
 arenito:{name:'Arenito',kind:'Rocha sedimentar · areia colada',color:'#e0c08a',text:'O arenito é areia que virou pedra: grãos de uma praia ou de um deserto antigo, apertados por camadas e camadas por cima, e colados por minerais que a água trouxe. Dá para ver as camadas, e às vezes as marcas das ondas de milhões de anos atrás.',detail:'As chapadas e as cidades de pedra do Brasil (Vila Velha, Sete Cidades, Chapada dos Guimarães) são arenito.',medio:'Rocha sedimentar clástica: grãos de 0,06 a 2 mm, em geral quartzo, com cimento de sílica, carbonato ou óxido de ferro. Estratificação cruzada indica dunas ou correntes.'},
 calcario:{name:'Calcário',kind:'Rocha sedimentar · conchas e corais',color:'#e8e0c8',text:'O calcário é feito de conchas, corais e esqueletos minúsculos que se acumularam no fundo de mares antigos. É claro, fosco e meio mole: a água da chuva dissolve e forma cavernas. É daqui que vem o cimento e a cal.',detail:'As grutas de Bonito e de Minas Gerais são calcário dissolvido pela água.',medio:'Composição: carbonato de cálcio (calcita). Reage com ácido clorídrico diluído (efervescência). Pode ser bioquímico (recifal) ou químico (precipitação).'},
 carvao:{name:'Carvão mineral',kind:'Rocha sedimentar · floresta soterrada',color:'#22201e',text:'O carvão é uma floresta antiga que virou pedra. Plantas de pântanos morreram, afundaram na lama sem apodrecer e ficaram enterradas por milhões de anos, cada vez mais apertadas, até virar essa rocha preta que pega fogo. Por isso ele é um combustível fóssil.',detail:'As jazidas brasileiras ficam no sul (Santa Catarina e Rio Grande do Sul), de florestas de 280 milhões de anos.',medio:'Rocha sedimentar orgânica: turfa → linhito → hulha → antracito, com teor de carbono crescente. Queimá-lo devolve à atmosfera CO₂ guardado há milhões de anos.'},
 marmore:{name:'Mármore',kind:'Rocha metamórfica · calcário cozido',color:'#f0ecea',text:'O mármore é calcário que foi enterrado, cozido e apertado até os grãos se reorganizarem. Fica liso, branco ou colorido, com veios, e brilha quando polido. É a rocha das estátuas e dos pisos.',detail:'O Davi de Michelangelo foi esculpido num bloco de mármore de Carrara, na Itália.',medio:'Metamorfismo da calcita recristaliza os grãos (textura granoblástica) e apaga fósseis e estratificação. Veios vêm de impurezas (argila, óxidos).'},
 ardosia:{name:'Ardósia',kind:'Rocha metamórfica · lama apertada',color:'#4a4e58',text:'A ardósia é lama que virou rocha e depois foi apertada de lado, dentro da Terra. Por isso ela se parte em placas finas e retas: era usada nas lousas das escolas antigas e ainda cobre telhados e pisos.',detail:'O Brasil é um dos maiores produtores do mundo, em Minas Gerais.',medio:'Metamorfismo de baixo grau de folhelhos: a foliação (clivagem ardosiana) é perpendicular à pressão, independente das camadas originais.'},
 quartzo:{name:'Quartzo',kind:'Mineral · o mais comum',color:'#e8f0f8',text:'O quartzo é o mineral mais comum da crosta. É duro, transparente ou branco, e forma cristais em ponta de seis lados. Está no granito, na areia da praia, no vidro e no relógio de pulso, onde ele vibra e marca o tempo.',detail:'Dureza 7 na escala de Mohs: risca o vidro. A ametista e o citrino são quartzo colorido.',medio:'SiO₂, sistema trigonal. Piezoelétrico: gera tensão elétrica sob pressão, por isso é usado em osciladores.'},
 feldspato:{name:'Feldspato',kind:'Mineral · o mais abundante',color:'#f0c0b0',text:'O feldspato é o mineral mais abundante da Terra: é mais da metade da crosta. São os grãos rosados ou brancos, de faces retas, do granito. Quando o feldspato apodrece com a chuva, vira argila, a matéria-prima do tijolo e da cerâmica.',detail:'Dureza 6. A porcelana leva feldspato na receita.',medio:'Grupo de silicatos de alumínio com K, Na ou Ca (ortoclásio, plagioclásio). Duas direções de clivagem em ângulo quase reto.'},
 mica:{name:'Mica',kind:'Mineral · lâminas brilhantes',color:'#c8a060',text:'A mica são aquelas lâminas brilhantes, prateadas ou pretas, que se soltam em folhas finas como papel. Está no granito e brilha na areia de alguns rios, o que já enganou muito garimpeiro. Aguenta calor e não conduz eletricidade.',detail:'Usada em janelas de fornos antigos e em cosméticos com brilho.',medio:'Filossilicatos (muscovita clara, biotita escura) com clivagem basal perfeita. Isolante térmico e elétrico.'},
 kola:{name:'Poço de Kola',kind:'Até onde chegamos',color:'#e8d8b0',text:'O buraco mais fundo que o ser humano já cavou fica na Rússia: o poço de Kola, com 12 quilômetros. Parece muito, mas é só 0,2 por cento do caminho até o centro. Lá no fundo a rocha estava a 180 graus, e as brocas não aguentaram mais.',detail:'Foram 20 anos de perfuração, de 1970 a 1992. O buraco tem 23 cm de largura.',medio:'A temperatura subiu mais rápido do que o previsto (gradiente de ~15 °C/km nas camadas profundas) e a rocha tornou-se plástica, fechando o poço.'}
};
